import 'package:cloud_firestore/cloud_firestore.dart';
class AurenFutureScenario {final String id,title,description,horizon,assumptions;final List<String> actions;const AurenFutureScenario({required this.id,required this.title,required this.description,required this.horizon,required this.assumptions,required this.actions});}
class AurenFutureSimulatorService {final FirebaseFirestore _db;AurenFutureSimulatorService({FirebaseFirestore? firestore}):_db=firestore??FirebaseFirestore.instance;DocumentReference<Map<String,dynamic>> _doc(String uid)=>_db.collection('users').doc(uid).collection('future_simulator').doc('current');Stream<List<AurenFutureScenario>> watch(String uid)=>_doc(uid).snapshots().map((d){if(!d.exists)return const <AurenFutureScenario>[];final raw=(d.data()?['scenarios'] as List?)??const[];return raw.whereType<Map>().map((m){final x=Map<String,dynamic>.from(m);return AurenFutureScenario(id:x['id'] as String? ?? '',title:x['title'] as String? ?? '',description:x['description'] as String? ?? '',horizon:x['horizon'] as String? ?? '',assumptions:x['assumptions'] as String? ?? '',actions:((x['actions'] as List?)??const[]).whereType<String>().toList());}).toList();});Future<void> save(String uid,List<AurenFutureScenario> ss)=>_doc(uid).set({'scenarios':ss.take(10).map((s)=>{'id':s.id,'title':s.title,'description':s.description,'horizon':s.horizon,'assumptions':s.assumptions,'actions':s.actions.take(10).toList()}).toList(),'updatedAt':FieldValue.serverTimestamp()});List<AurenFutureScenario> simulate({required String goal,required String currentState,required List<String> options})=>options.take(3).toList().asMap().entries.map((entry){final option=entry.value;final i=entry.key;return AurenFutureScenario(id:'scenario_'+(i+1).toString(),title:option,description:'Scenario based on '+option+'. Current context: '+currentState+'. Goal: '+goal+'.',horizon:i==0?'30 days':i==1?'90 days':'12 months',assumptions:'Planning scenario only, not a prediction. Results depend on execution, resources, timing, and external conditions.',actions:const ['Define the first measurable milestone','Test the assumption with a small reversible step','Review evidence before committing further']);}).toList();}